   132	function build_articles_query(array $params): string
   133	{
   134	  $clean = [];
   135	  foreach ($params as $key => $value) {
   136	    if ($value === '' || $value === null) {
   137	      continue;
   138	    }
   139	    if (is_int($value) && $value <= 0) {
   140	      continue;
   141	    }
   142	    $clean[$key] = $value;
   143	  }
   144	  $query = http_build_query($clean);
   145	  return $query === '' ? '' : ('?' . $query);
   146	}
