   366	/**
   367	 * Normalize tree nodes: value array + label sort + recursive children normalize.
   368	 *
   369	 * @param array<int|string,array<string,mixed>> $nodes
   370	 * @return array<int,array<string,mixed>>
   371	 */
   372	function normalize_tree_nodes(array $nodes): array
   373	{
   374	  $list = array_values($nodes);
   375	  usort($list, static function (array $a, array $b): int {
   376	    $countCmp = ((int) ($b['count'] ?? 0)) <=> ((int) ($a['count'] ?? 0));
   377	    if ($countCmp !== 0) {
   378	      return $countCmp;
   379	    }
   380	    return strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
   381	  });
   382	
   383	  foreach ($list as &$node) {
   384	    if (isset($node['children']) && is_array($node['children'])) {
   385	      /** @var array<int|string,array<string,mixed>> $children */
   386	      $children = $node['children'];
   387	      $node['children'] = normalize_tree_nodes($children);
   388	    }
   389	  }
   390	  return $list;
   391	}
